head.b:skin:
/* ----------------------------------------------------
   PRINT OFO — MODERN SOFTWARE LANDING PAGE THEME
   Author: KKR Kishan
   Version: 1.1.0
   ---------------------------------------------------- */
:root {
  --bg-dark: #070c18;
  --bg-surface: #0f172a;
  --bg-card: rgba(30, 41, 59, 0.7);
  --bg-card-hover: rgba(30, 41, 59, 0.95);
  --border-subtle: rgba(148, 163, 184, 0.12);
  --border-highlight: rgba(56, 189, 248, 0.3);
  --primary: #2563eb;
  --primary-light: #3b82f6;
  --accent-cyan: #06b6d4;
  --accent-emerald: #10b981;
  --accent-amber: #f59e0b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --shadow-glow: 0 0 35px rgba(37, 99, 235, 0.25);
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
  background-image: 
    radial-gradient(at 15% 10%, rgba(37, 99, 235, 0.15) 0px, transparent 50%),
    radial-gradient(at 85% 25%, rgba(6, 182, 212, 0.12) 0px, transparent 50%),
    radial-gradient(at 50% 80%, rgba(16, 185, 129, 0.08) 0px, transparent 50%);
  background-attachment: fixed;
}

a {
  color: inherit;
  text-decoration: none;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------------- HEADER / NAVBAR ---------------- */
header.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(7, 12, 24, 0.85);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-subtle);
  transition: all 0.3s ease;
}

.nav-wrapper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 76px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.5px;
}

.brand-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--primary), var(--accent-cyan));
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 20px;
  box-shadow: 0 4px 15px rgba(37, 99, 235, 0.4);
}

.brand-badge {
  font-size: 0.7rem;
  padding: 2px 8px;
  background: rgba(37, 99, 235, 0.15);
  border: 1px solid rgba(37, 99, 235, 0.4);
  color: var(--accent-cyan);
  border-radius: 999px;
  margin-left: 6px;
  font-weight: 600;
}

.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
  list-style: none;
}

.nav-links a {
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.95rem;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--text-main);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.btn-header-cta {
  background: linear-gradient(135deg, var(--primary), #1d4ed8);
  color: #fff;
  padding: 10px 20px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.9rem;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);
  transition: transform 0.2s, box-shadow 0.2s;
}

.btn-header-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(37, 99, 235, 0.5);
}

/* ---------------- HERO SECTION ---------------- */
.hero {
  padding: 90px 0 60px;
  text-align: center;
  position: relative;
}

.hero-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  border-radius: 999px;
  background: rgba(6, 182, 212, 0.1);
  border: 1px solid rgba(6, 182, 212, 0.3);
  color: var(--accent-cyan);
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 24px;
}

.hero-pill .dot {
  width: 8px;
  height: 8px;
  background: var(--accent-cyan);
  border-radius: 50%;
  box-shadow: 0 0 10px var(--accent-cyan);
}

.hero h1 {
  font-size: clamp(2.4rem, 5vw, 4.2rem);
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.15;
  margin-bottom: 24px;
}

.gradient-text {
  background: linear-gradient(135deg, #ffffff 30%, #93c5fd 65%, #38bdf8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero p.lead {
  max-width: 740px;
  margin: 0 auto 36px;
  font-size: 1.18rem;
  color: var(--text-muted);
  font-weight: 400;
}

.hero-cta-group {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: #fff;
  padding: 15px 32px;
  border-radius: var(--radius-md);
  font-weight: 700;
  font-size: 1.05rem;
  box-shadow: 0 10px 25px rgba(37, 99, 235, 0.4);
  transition: all 0.25s ease;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 15px 35px rgba(37, 99, 235, 0.55);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(30, 41, 59, 0.8);
  color: var(--text-main);
  padding: 15px 28px;
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 1.05rem;
  border: 1px solid var(--border-subtle);
  backdrop-filter: blur(10px);
  transition: all 0.25s ease;
}

.btn-secondary:hover {
  background: rgba(51, 65, 85, 0.9);
  border-color: var(--border-highlight);
  transform: translateY(-3px);
}

.hero-meta {
  display: flex;
  justify-content: center;
  gap: 32px;
  font-size: 0.88rem;
  color: var(--text-dim);
  flex-wrap: wrap;
}

.hero-meta span {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ---------------- STATS COUNTER BAR ---------------- */
.stats-bar {
  margin: 40px auto 70px;
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
  text-align: center;
}

.stat-item h3 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--accent-cyan);
  margin-bottom: 4px;
}

.stat-item p {
  font-size: 0.9rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* ---------------- PROBLEM & SOLUTION ---------------- */
.section-header {
  text-align: center;
  margin-bottom: 56px;
}

.section-tag {
  text-transform: uppercase;
  font-size: 0.78rem;
  letter-spacing: 1.5px;
  color: var(--accent-cyan);
  font-weight: 700;
  margin-bottom: 12px;
  display: inline-block;
}

.section-title {
  font-size: clamp(1.8rem, 3.5vw, 2.7rem);
  font-weight: 800;
  letter-spacing: -0.8px;
  margin-bottom: 16px;
}

.section-desc {
  max-width: 650px;
  margin: 0 auto;
  color: var(--text-muted);
  font-size: 1.05rem;
}

.comparison-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  margin-bottom: 80px;
}

@media (max-width: 768px) {
  .comparison-grid {
    grid-template-columns: 1fr;
  }
}

.compare-card {
  padding: 36px;
  border-radius: var(--radius-lg);
  position: relative;
}

.compare-card.bad {
  background: rgba(239, 68, 68, 0.04);
  border: 1px solid rgba(239, 68, 68, 0.2);
}

.compare-card.good {
  background: rgba(16, 185, 129, 0.05);
  border: 1px solid rgba(16, 185, 129, 0.3);
  box-shadow: 0 0 35px rgba(16, 185, 129, 0.08);
}

.compare-card h3 {
  font-size: 1.35rem;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.compare-card.bad h3 {
  color: #f87171;
}

.compare-card.good h3 {
  color: #34d399;
}

.compare-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.compare-list li {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  color: var(--text-muted);
  font-size: 0.98rem;
}

.compare-list li span.icon {
  font-size: 1.1rem;
  line-height: 1.4;
}

/* ---------------- FEATURES GRID ---------------- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
  margin-bottom: 90px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 32px;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--border-highlight), transparent);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.feature-card:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-highlight);
  transform: translateY(-5px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.3);
}

.feature-card:hover::before {
  opacity: 1;
}

.feature-icon-box {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 20px;
  background: rgba(37, 99, 235, 0.15);
  border: 1px solid rgba(37, 99, 235, 0.3);
  color: #60a5fa;
}

.feature-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* ---------------- SUPPORTED PRINTERS ---------------- */
.printers-section {
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.7) 0%, rgba(7, 12, 24, 0.9) 100%);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 56px 40px;
  margin-bottom: 90px;
}

.printer-badges {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px;
  margin-top: 36px;
}

.printer-chip {
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid var(--border-subtle);
  padding: 12px 20px;
  border-radius: 999px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.92rem;
  font-weight: 600;
  transition: all 0.2s;
}

.printer-chip:hover {
  border-color: var(--accent-cyan);
  background: rgba(37, 99, 235, 0.15);
  transform: translateY(-2px);
}

.printer-chip span.brand {
  color: var(--accent-cyan);
  font-weight: 800;
}

/* ---------------- HOW IT WORKS ---------------- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
  margin-bottom: 90px;
}

.step-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 36px 28px;
  position: relative;
}

.step-number {
  position: absolute;
  top: -16px;
  left: 28px;
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, var(--primary), var(--accent-cyan));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  color: #fff;
  font-size: 0.9rem;
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.4);
}

.step-card h3 {
  font-size: 1.2rem;
  margin: 12px 0 10px;
}

.step-card p {
  color: var(--text-muted);
  font-size: 0.92rem;
}

/* ---------------- DOWNLOAD MATRIX SECTION ---------------- */
.download-section {
  background: radial-gradient(circle at center, rgba(37, 99, 235, 0.12) 0%, transparent 70%);
  padding: 70px 0;
  margin-bottom: 80px;
}

.download-cards-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  max-width: 960px;
  margin: 0 auto 40px;
}

@media (max-width: 768px) {
  .download-cards-grid {
    grid-template-columns: 1fr;
  }
}

.dl-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  text-align: center;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all 0.3s;
  position: relative;
}

.dl-card.highlight {
  border-color: rgba(37, 99, 235, 0.5);
  background: rgba(30, 41, 59, 0.85);
  box-shadow: var(--shadow-glow);
}

.dl-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid rgba(16, 185, 129, 0.4);
  color: var(--accent-emerald);
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.75rem;
  font-weight: 700;
}

.dl-icon {
  font-size: 48px;
  margin-bottom: 16px;
}

.dl-card h3 {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.dl-card p.version {
  font-size: 0.88rem;
  color: var(--accent-cyan);
  margin-bottom: 16px;
  font-family: 'JetBrains Mono', monospace;
}

.dl-card ul.specs {
  list-style: none;
  text-align: left;
  margin: 20px 0 30px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 0.9rem;
  color: var(--text-muted);
}

.dl-card ul.specs li {
  display: flex;
  align-items: center;
  gap: 8px;
}

.terminal-box {
  max-width: 780px;
  margin: 0 auto;
  background: #030712;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: 'JetBrains Mono', monospace;
  font-size: 0.9rem;
  color: #38bdf8;
}

.terminal-box code {
  background: transparent;
  color: #38bdf8;
}

/* ---------------- FAQ ACCORDION ---------------- */
.faq-grid {
  max-width: 840px;
  margin: 0 auto 90px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.faq-item {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 24px 28px;
  transition: all 0.2s;
}

.faq-item:hover {
  border-color: var(--border-highlight);
}

.faq-item h4 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.faq-item p {
  color: var(--text-muted);
  font-size: 0.96rem;
  line-height: 1.6;
}

/* ---------------- BLOG POSTS SECTION (Blogger Requirement) ---------------- */
.blog-posts-section {
  padding: 40px 0;
  border-top: 1px solid var(--border-subtle);
  margin-top: 40px;
}

/* ---------------- FOOTER ---------------- */
footer.site-footer {
  background: #030712;
  border-top: 1px solid var(--border-subtle);
  padding: 60px 0 30px;
  color: var(--text-dim);
  font-size: 0.9rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 40px;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

.footer-col h4 {
  color: var(--text-main);
  font-size: 1rem;
  margin-bottom: 16px;
  font-weight: 700;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col ul a:hover {
  color: var(--text-main);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
